
#' Obtain Open Targets molecular QTL credible sets
#'
#' Adds the Open Targets Platform fine-mapped molecular QTL credible sets (eQTL,
#' pQTL, sQTL, tuQTL and their single-cell versions, from GTEx, the eQTL
#' Catalogue and others) that contain the index SNP to a 'locus' object.
#' Open Targets is GRCh38; for a GRCh37 locus, credible-set lead variants are
#' placed at their position in `loc$data` when present, otherwise shifted by
#' the index SNP's GRCh38 - GRCh37 offset, which is approximate away from it.
#'
#' @param loc Object of class 'locus' generated by [locus()]. Its index SNP must
#'   be an rsID.
#' @param study_types Open Targets QTL study types to include.
#' @param trans Logical whether to include trans-QTL credible sets.
#' @return Returns an object of class 'locus' with an extra list element
#'   'OTqtl', a dataframe with one row per credible set, or unchanged if no
#'   credible sets contain the index SNP.
#' @noRd

link_ot <- function(loc,
                    study_types = c("eqtl", "pqtl", "sqtl", "tuqtl", "sceqtl",
                                    "scpqtl", "scsqtl", "sctuqtl"),
                    trans = FALSE) {
  if (!inherits(loc, "locus")) stop("Not a locus object")
  if (!requireNamespace("httr", quietly = TRUE)) {
    stop("Package 'httr' must be installed to use this feature", call. = FALSE)
  }
  index_snp <- loc$index_snp
  if (!grepl("^rs[0-9]+$", index_snp)) {
    stop("Open Targets lookup needs an rsID index SNP", call. = FALSE)
  }
  start <- Sys.time()
  message("Open Targets ", index_snp, appendLF = FALSE)
  vid <- ot_variant_id(index_snp, loc$seqname)
  if (is.null(vid)) {
    message(" - not found in Open Targets")
    return(loc)
  }
  res <- ot_qtl_sets(vid, study_types)
  q <- ot_qtl_df(res$rows)
  if (!trans) q <- q[!q$trans, ]
  if (nrow(q) == 0) {
    message(" - no QTL credible sets contain ", index_snp)
    return(loc)
  }
  ind <- match(q$lead_rsid, loc$data[, loc$labs])
  offset <- 0
  if (!grepl("38", loc$genome)) {
    i <- match(index_snp, loc$data[, loc$labs])
    offset <- if (!is.na(i)) {
      res$position - loc$data[i, loc$pos]
    } else {
      # index SNP not in the data (e.g. only in zoom()'s second GWAS)
      stats::median(q$pos38[!is.na(ind)] - loc$data[ind[!is.na(ind)], loc$pos])
    }
  }
  q$pos <- ifelse(is.na(ind), q$pos38 - offset, loc$data[ind, loc$pos])
  loc$OTqtl <- q
  message(" - ", nrow(q), " QTL credible sets (",
          format(Sys.time() - start, digits = 3), ")")
  loc
}

# POST a GraphQL query to the Open Targets Platform API; returns the data element
ot_graphql <- function(query, variables = list()) {
  r <- httr::POST("https://api.platform.opentargets.org/api/v4/graphql",
                  body = list(query = query, variables = variables),
                  encode = "json")
  httr::stop_for_status(r)
  d <- httr::content(r, as = "parsed", simplifyVector = FALSE)
  if (!is.null(d$errors)) stop("Open Targets: ", d$errors[[1]]$message)
  d$data
}

mem_ot_graphql <- memoise(ot_graphql)

# rsID -> Open Targets variant ID (CHROM_POS_REF_ALT, GRCh38), or NULL; the
# search also returns prefix matches (rs1 -> rs10...), so check the rsID
ot_variant_id <- function(rsid, chr = NULL) {
  d <- mem_ot_graphql(
    'query q($s: String!) { search(queryString: $s, entityNames: ["variant"]) { hits { id object { ... on Variant { rsIds chromosome } } } } }',
    list(s = rsid))
  ok <- vapply(d$search$hits, function(h) {
    rsid %in% unlist(h$object$rsIds) &&
      (is.null(chr) || identical(h$object$chromosome, sub("^chr", "", chr)))
  }, logical(1))
  if (!any(ok)) NULL else d$search$hits[[which(ok)[1]]]$id
}

ot_qtl_query <- 'query q($v: String!, $t: [StudyTypeEnum!], $i: Int!) {
  variant(variantId: $v) { id rsIds position
    credibleSets(studyTypes: $t, page: {index: $i, size: 50}) { count rows {
      studyLocusId studyType pValueMantissa pValueExponent beta isTransQtl
      variant { id rsIds position }
      study { id projectId condition target { approvedSymbol }
              biosample { biosampleName } }
      locus(variantIds: [$v]) { rows { posteriorProbability } } } } } }'

# all QTL credible sets containing variant vid, paged; list(position, rows)
ot_qtl_sets <- function(vid, study_types) {
  rows <- list()
  i <- 0L
  repeat {
    d <- mem_ot_graphql(ot_qtl_query, list(v = vid, t = as.list(study_types), i = i))
    cs <- d$variant$credibleSets
    rows <- c(rows, cs$rows)
    i <- i + 1L
    if (length(rows) >= cs$count || length(cs$rows) == 0) break
  }
  list(position = d$variant$position, rows = rows)
}

# Open Targets study types -> display labels; unknown types pass through
qtl_label <- function(x) {
  lab <- c(eqtl = "eQTL", pqtl = "pQTL", sqtl = "sQTL", tuqtl = "tuQTL",
           sceqtl = "sc-eQTL", scpqtl = "sc-pQTL", scsqtl = "sc-sQTL",
           sctuqtl = "sc-tuQTL")
  ifelse(x %in% names(lab), lab[x], x)
}

ot_qtl_df <- function(rows) {
  `%||%` <- function(a, b) if (is.null(a)) b else a
  get1 <- function(f) vapply(rows, function(r) as.character(f(r) %||% NA), character(1))
  q <- data.frame(
    id = get1(function(r) r$studyLocusId),
    type = qtl_label(get1(function(r) r$studyType)),
    gene = get1(function(r) r$study$target$approvedSymbol),
    biosample = get1(function(r) r$study$biosample$biosampleName),
    condition = get1(function(r) r$study$condition),
    study = get1(function(r) r$study$id),
    project = get1(function(r) r$study$projectId),
    lead_id = get1(function(r) r$variant$id),
    lead_rsid = get1(function(r) unlist(r$variant$rsIds)[1]),
    pos38 = as.numeric(get1(function(r) r$variant$position)),
    p = as.numeric(get1(function(r) r$pValueMantissa)) *
      10^as.numeric(get1(function(r) r$pValueExponent)),
    beta = as.numeric(get1(function(r) r$beta)),
    pip = as.numeric(get1(function(r) unlist(lapply(r$locus$rows, `[[`, "posteriorProbability"))[1])),
    trans = get1(function(r) r$isTransQtl) %in% "TRUE"
  )
  q$logP <- -log10(q$p)
  q
}

#' Locus scatter plotly for Open Targets QTL credible sets
#'
#' One point per credible set at its lead variant: colour = QTL type, marker
#' size = posterior inclusion probability (PIP) of the index SNP in the set.
#'
#' @param loc Object of class 'locus' with element `OTqtl` from `link_ot()`.
#' @param type_filter Character vector of QTL types to show.
#' @param gene_filter Character vector of QTL genes to show.
#' @param ... Optional arguments passed to `plot_ly()`.
#' @returns A `plotly` scatter plot.
#' @noRd

qtl_plotly <- function(loc, type_filter = NULL, gene_filter = NULL, ...) {
  xlim <- loc$xrange / 1e6
  xlim <- xlim + diff(xlim) * c(-0.01, 0.01)
  xlab <- paste("Chromosome", loc$seqname, "(Mb)")
  q <- loc$OTqtl
  if (!is.null(type_filter) && !is.null(q)) q <- q[q$type %in% type_filter, ]
  if (!is.null(gene_filter) && !is.null(q)) q <- q[q$gene %in% gene_filter, ]
  cfg <- function(p) plotly::config(p, displaylogo = FALSE,
    modeBarButtonsToRemove = c("select2d", "lasso2d", "autoScale2d",
                               "resetScale2d", "hoverClosest", "hoverCompare"),
    toImageButtonOptions = list(format = "svg"))

  if (is.null(q) || nrow(q) == 0) {
    blank <- data.frame(pos = numeric(0), logP = numeric(0))
    p <- plot_ly(blank, x = ~pos, y = ~logP, showlegend = FALSE,
                 source = "plotly_locus", type = "scattergl", mode = "markers",
                 ...) %>%
      plotly::layout(xaxis = list(title = xlab, ticks = "outside",
                                  zeroline = FALSE, showgrid = FALSE,
                                  range = as.list(xlim)),
                     yaxis = list(title = "", showticklabels = FALSE,
                                  zeroline = FALSE, showgrid = FALSE),
                     annotations = list(x = 0.5, y = 0.5, text = "No QTL data",
                                        xref = "paper", yref = "paper",
                                        showarrow = FALSE))
    return(cfg(p))
  }

  scheme <- c(eQTL = "#1f77b4", sQTL = "#ff7f0e", tuQTL = "#2ca02c",
              pQTL = "#d62728", `sc-eQTL` = "#9467bd", `sc-sQTL` = "#8c564b",
              `sc-tuQTL` = "#e377c2", `sc-pQTL` = "#bcbd22")
  col <- scheme[q$type]
  col[is.na(col)] <- "grey"
  ylim <- range(q$logP, na.rm = TRUE)
  ylim <- ylim + max(diff(ylim) * 0.05, 0.5) * c(-1, 1)
  hovertext <- paste0(q$lead_rsid,
                      "<br>Chr ", loc$seqname, ": ", q$pos,
                      "<br>Type: ", q$type,
                      "<br>Gene: ", q$gene,
                      "<br>Tissue/cell: ", ellipsis(q$biosample),
                      ifelse(is.na(q$condition), "",
                             paste0(" (", ellipsis(q$condition), ")")),
                      "<br>P = ", signif(q$p, 3), ", beta = ", signif(q$beta, 3),
                      "<br>PIP of ", loc$index_snp, " = ", signif(q$pip, 3),
                      "<br>Study: ", ellipsis(q$study))

  p <- plot_ly(x = q$pos / 1e6, y = q$logP,
               marker = list(opacity = 0.8, size = 6 + 14 * sqrt(ifelse(is.na(q$pip), 0, q$pip)),
                             color = I(col),
                             line = list(width = 1, color = "black")),
               text = hovertext, hoverinfo = "text", key = q$lead_rsid,
               showlegend = FALSE, source = "plotly_locus",
               type = "scattergl", mode = "markers", ...) %>%
    plotly::layout(xaxis = list(title = xlab, ticks = "outside",
                                zeroline = FALSE, showgrid = FALSE,
                                range = as.list(xlim)),
                   yaxis = list(title = "QTL -log<sub>10</sub> P",
                                ticks = "outside", fixedrange = TRUE,
                                showline = TRUE, range = ylim),
                   dragmode = "pan")
  attr(p, "eqtl_genes") <- unique(q$gene)
  cfg(p)
}

# shorten long Open Targets labels (study IDs reach ~95 characters) for hovers
ellipsis <- function(x, n = 40) {
  ifelse(!is.na(x) & nchar(x) > n, paste0(substr(x, 1, n - 1), "\u2026"), x)
}

#' Table of Open Targets QTL credible sets for zoom()'s Table tab
#'
#' @param loc List or 'locus' object with element `OTqtl`.
#' @param type_filter,gene_filter See `qtl_plotly()`.
#' @return Dataframe sorted by P value, or `NULL` if there is no QTL data.
#' @noRd

qtl_table <- function(loc, type_filter = NULL, gene_filter = NULL) {
  q <- loc$OTqtl
  if (is.null(q)) return(NULL)
  if (!is.null(type_filter)) q <- q[q$type %in% type_filter, ]
  if (!is.null(gene_filter)) q <- q[q$gene %in% gene_filter, ]
  tab <- data.frame(`Lead SNP` = q$lead_rsid, Position = q$pos, Type = q$type,
                    Gene = q$gene, `Tissue/cell` = q$biosample,
                    Condition = q$condition, P = q$p, Beta = q$beta,
                    PIP = q$pip, Study = q$study, Project = q$project,
                    check.names = FALSE)
  tab <- tab[order(tab$P), ]
  rownames(tab) <- NULL
  tab
}
